CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE NOT NULL COLLATE NOCASE,email TEXT UNIQUE NOT NULL COLLATE NOCASE,pass TEXT NOT NULL,city TEXT NOT NULL,phone TEXT,avatar TEXT,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS books(id INTEGER PRIMARY KEY AUTOINCREMENT,owner_id INTEGER NOT NULL,title TEXT NOT NULL,author TEXT NOT NULL,cat TEXT NOT NULL,cond TEXT NOT NULL,value INTEGER NOT NULL,img TEXT,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS wishes(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,title TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS requests(id INTEGER PRIMARY KEY AUTOINCREMENT,from_id INTEGER NOT NULL,to_id INTEGER NOT NULL,want_id INTEGER NOT NULL,offer_id INTEGER NOT NULL,money INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'pending',created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS i_books_owner ON books(owner_id);
CREATE INDEX IF NOT EXISTS i_sessions_user ON sessions(user_id);
